      wh.bins = (await db.query(`SELECT b.*, z.name as zone_name FROM warehouse_bins b LEFT JOIN warehouse_zones z ON b.zone_id = z.id WHERE b.warehouse_id = $1 ORDER BY b.bin_code ASC`, [wh.id])).rows;
